@Service
public class PaymentService {

    @Autowired
    private RedisTemplate<String, String>
        redisTemplate;

    @Autowired
    private PaymentRepository paymentRepository;

    @Transactional
    public PaymentResponse processPayment(
            String idempotencyKey,
            PaymentRequest request) {

        // Enforce Idempotency via Atomic Redis Set
        Boolean acquired = redisTemplate.opsForValue()
            .setIfAbsent("lock:idmp:" + idempotencyKey,
                         "PROCESSING",
                         Duration.ofMinutes(10));

        if (Boolean.FALSE.equals(acquired)) {
            throw new DuplicateRequestException(
                "Operation currently processing or completed"
            );
        }

        try {
            // Execute domain logic safely
            Payment payment = new Payment(request);
            paymentRepository.save(payment);

            redisTemplate.opsForValue().set(
                "lock:idmp:" + idempotencyKey, 
                "COMPLETED"
            );

            return new PaymentResponse(payment.getId(), "SUCCESS");
        } catch (Exception e) {
            redisTemplate.delete("lock:idmp:" + idempotencyKey);
            throw e;
        }
    }
}
